import '@kerfjs/ui/layout.css';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { MenuHeader, MenuItem } from '@kerfjs/ui/menu';
import { PageHeader } from '@kerfjs/ui/page-header';
import { ResizableRegion, wireResizableRegions } from '@kerfjs/ui/resizable-region';

export function mountAppShell(root: HTMLElement, app: { navigate(id: string): void; setInspectorWidth(px: number): void; load(): void }) {
  root.className = 'kui-layout app-shell';
  root.innerHTML = `
    <header data-app-toolbar></header>
    <div class="app-body">
      <nav class="kui-sidebar" aria-label="Workspace navigation">
        <section class="kui-sidebar-section"><div data-nav-header></div><div data-nav-items></div></section>
      </nav>
      <main class="workspace" tabindex="-1"><div data-page-header></div><div class="workspace-scroll" tabindex="0" aria-label="Workspace content"></div></main>
      <div data-inspector-resizer></div>
      <aside class="inspector" aria-label="Inspector"><div class="inspector-scroll" tabindex="0"></div></aside>
    </div>`;
  Toolbar({ target: root.querySelector('[data-app-toolbar]')!, label: 'Project toolbar' });
  PageHeader({ target: root.querySelector('[data-page-header]')!, title: 'Workspace' });
  MenuHeader({ target: root.querySelector('[data-nav-header]')!, label: 'Workspace' });
  MenuItem({ target: root.querySelector('[data-nav-items]')!, label: 'Overview', selected: true, onSelect: () => app.navigate('overview') });
  MenuItem({ target: root.querySelector('[data-nav-items]')!, label: 'Tasks', onSelect: () => app.navigate('tasks') });
  ResizableRegion({ target: root.querySelector('[data-inspector-resizer]')!, orientation: 'vertical', label: 'Resize inspector' });
  const disposeResize = wireResizableRegions(root, { onResize: ({ size }) => app.setInspectorWidth(size) });
  app.load();
  return () => disposeResize();
}

