.workspace-scroll, .inspector-scroll { min-block-size: 0; overflow: auto; }
@media (max-width: 44rem) { .app-body { grid-template-columns: minmax(0, 1fr); } .kui-sidebar, .inspector, [data-inspector-resizer] { display: none; } }
